package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.os.ParcelFileDescriptor;import java.io.*;import com.shockwave.pdfium.*;
final class PdfPages {
 static class Page {Bitmap image;int count;String title="",author="";}
 static Page render(Context context,File file,int page,int maxWidth,int maxHeight)throws Exception{PdfiumCore core;try{core=new PdfiumCore(context);}catch(LinkageError e){throw new IOException("PDF native library does not support this device");}ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfDocument doc=null;try{doc=core.newDocument(fd);Page result=new Page();result.count=core.getPageCount(doc);if(result.count<1||result.count>20000)throw new IOException("Unsupported PDF page count");int index=Math.max(0,Math.min(result.count-1,page));core.openPage(doc,index);int width=core.getPageWidthPoint(doc,index),height=core.getPageHeightPoint(doc,index);if(width<1||height<1)throw new IOException("Invalid PDF page dimensions");float scale=Math.min(maxWidth/(float)width,maxHeight/(float)height);int w=Math.max(1,Math.round(width*scale)),h=Math.max(1,Math.round(height*scale));result.image=Bitmap.createBitmap(w,h,Bitmap.Config.RGB_565);result.image.eraseColor(Color.WHITE);core.renderPageBitmap(doc,result.image,index,0,0,w,h,true);PdfDocument.Meta meta=core.getDocumentMeta(doc);if(meta!=null){result.title=meta.getTitle()==null?"":meta.getTitle();result.author=meta.getAuthor()==null?"":meta.getAuthor();}return result;}finally{if(doc!=null)core.closeDocument(doc);try{fd.close();}catch(Exception ignored){}}}
}
